from visual013 import *
def main():
 n='G03';cid=next(v['id']for v in getcase(n)['views']if v['role']=='FIT');a=np.load(R/'inputs'/n/(cid+'.npz'));V=np.load(R/'inputs'/n/'INITIAL.npz')['V'];T=a['T'];K=a['K'];cam=(V-T[:3,3])@T[:3,:3];pix=cam@K.T;uv=pix[:,:2]/pix[:,2:];base=np.load(R/'local_results'/('GRADIENT_'+n+'_A0.npz'))['gradient'];fig,axs=plt.subplots(1,4,figsize=(20,5));receipts=[]
 for ax,arm in zip(axs,['A0','A1','A2','A3']):
  g=np.load(R/'local_results'/('GRADIENT_'+n+'_'+arm+'.npz'))['gradient'];component=g if arm=='A0'else g-base;W=V-.02*component;pp=(W-T[:3,3])@T[:3,:3]@K.T;up=pp[:,:2]/pp[:,2:];delta=up-uv;norm=np.linalg.norm(delta,axis=1);keep=(cam[:,2]>0)&(uv[:,0]>=0)&(uv[:,0]<640)&(uv[:,1]>=0)&(uv[:,1]<360);ids=np.flatnonzero(keep);ids=ids[np.argsort(norm[ids])[-70:]];factor=20/max(1e-12,float(norm[ids].max()));ax.imshow(a['RGB']);edge(ax,a['labels']==1,'lime');ax.quiver(uv[ids,0],uv[ids,1],delta[ids,0]*factor,delta[ids,1]*factor,color='yellow',angles='xy',scale_units='xy',scale=1,width=.002);ax.set_title(arm+(' full objective'if arm=='A0'else' added term only')+'\n-0.02 gradient projected; display x%.2g'%factor,fontsize=9);ax.axis('off');receipts.append(dict(case=n,view=cid,arm=arm,display_factor=factor,actual_max_projected_probe_px=float(norm[ids].max()),gradient_norm=float(np.linalg.norm(component)),actual_optimizer_step=False,meaning='negative loss-gradient visualization only, not momentum Adam update'))
 fig.suptitle('G03 true loss-gradient components at shared011FINAL | raw Mask unchanged\nArrows computed from actual full vertex derivatives; magnification explicitly labeled, not inferred movement.');finish(fig,'full/G03_Actual_Loss_Gradients.png');save('metrics/GRADIENT_ARROW_RECEIPT.json',receipts)
if __name__=='__main__':main()
